import React from 'react';
import { Link } from 'react-router-dom';
import { Menu, X } from 'lucide-react';
import munLogo from '../assets/images/MUN.png';

const Navbar = ({ darkMode, setDarkMode, scrolled, mobileMenuOpen, setMobileMenuOpen }) => {

  const navLinks = [
    { name: 'Home', href: '#home' },
    { name: 'About', href: '#about' },
    { name: 'Services', href: '#services' },
    { name: 'Portfolio', href: '#portfolio' },
    { name: 'Tech', href: '#technologies' },
    { name: 'Contact', href: '#contact' },
  ];

  return (
    <nav 
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        scrolled 
          ? 'bg-[#0a1628]/90 backdrop-blur-md py-3 shadow-lg' 
          : 'bg-transparent py-5'
      }`}
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between">
          {/* Logo */}
          <a href="#home" className="flex items-center gap-2 group">
            <div className="w-10 h-10 rounded-full flex items-center justify-center transform group-hover:scale-110 transition-transform duration-300 overflow-hidden">
              <img 
                src={munLogo} 
                alt="MUN Logo" 
                className="w-10 h-10 object-cover"
              />
            </div>
            <span className="text-xl font-bold text-white">
              Project <span className="gradient-text">MUN</span>
            </span>
          </a>

          {/* Desktop Navigation */}
          <div className="hidden md:flex items-center gap-8">
            {navLinks.map((link) => (
              <a
                key={link.name}
                href={link.href}
                className="nav-link text-sm font-medium text-gray-300 hover:text-white transition-colors"
              >
                {link.name}
              </a>
            ))}

            {/* Login Link */}
            <Link
              to="/login"
              className="nav-link text-sm font-medium text-gray-300 hover:text-white transition-colors"
            >
              Login
            </Link>

            {/* Dashboard Link */}
            <Link
              to="/dashboard"
              className="nav-link text-sm font-medium text-blue-400 hover:text-blue-300 transition-colors"
            >
              Dashboard
            </Link>

            {/* Contact Button */}
            <a href="#contact">
              <button className="px-5 py-2 bg-white text-[#0a1628] hover:bg-gray-200 rounded-full text-sm font-medium transition-colors">
                Contact Us
              </button>
            </a>
          </div>

          {/* Mobile Menu Button */}
          <div className="md:hidden flex items-center gap-4 relative z-50">
            <button
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
              className={`p-2 rounded-lg transition-all duration-300 relative z-50 ${
                mobileMenuOpen 
                  ? 'bg-blue-600 text-white shadow-lg shadow-blue-500/50 ring-2 ring-white/30' 
                  : 'text-white hover:bg-white/10'
              }`}
            >
              {mobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
            </button>
          </div>
        </div>

        {/* Mobile Menu */}
        <div className={`md:hidden ${mobileMenuOpen ? 'pointer-events-auto' : 'pointer-events-none'}`}>
          {/* Backdrop blur overlay */}
          <div 
            className={`fixed inset-0 bg-black/40 backdrop-blur-sm z-40 transition-all duration-500 ease-out ${
              mobileMenuOpen ? 'opacity-100' : 'opacity-0'
            }`}
            onClick={() => setMobileMenuOpen(false)}
          ></div>

          {/* Menu content */}
          <div className={`fixed top-16 left-4 right-4 z-50 transition-all duration-500 ease-out ${
            mobileMenuOpen ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-4'
          }`}>
            <div className="rounded-2xl p-4 bg-[#0a1628]/95 backdrop-blur-xl border border-white/10 shadow-2xl">
              {navLinks.map((link, index) => (
                <a
                  key={link.name}
                  href={link.href}
                  onClick={() => setMobileMenuOpen(false)}
                  className="block py-3 px-4 rounded-lg text-sm font-medium text-gray-300 hover:text-white hover:bg-white/10 transition-all duration-300"
                  style={{ transitionDelay: mobileMenuOpen ? `${index * 50}ms` : '0ms' }}
                >
                  {link.name}
                </a>
              ))}
              <Link
                to="/login"
                onClick={() => setMobileMenuOpen(false)}
                className="block py-3 px-4 rounded-lg text-sm font-medium text-gray-300 hover:text-white hover:bg-white/10 transition-all duration-300"
              >
                Login
              </Link>
              <Link
                to="/dashboard"
                onClick={() => setMobileMenuOpen(false)}
                className="block py-3 px-4 rounded-lg text-sm font-medium text-blue-400 hover:text-blue-300 hover:bg-blue-500/10 transition-all duration-300"
              >
                Dashboard
              </Link>
              <div className="pt-2 border-t border-white/10 mt-2">
                <a href="#contact" onClick={() => setMobileMenuOpen(false)}>
                  <button className="w-full py-3 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-500 transition-all duration-300">
                    Contact Us
                  </button>
                </a>
              </div>
            </div>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
